-- 1) Hauptsitz: bestehende Zeile `leptos-estates` aktualisieren
update public.directory_listings set
  type = 'vendor', category_group = 'realestate', subtype = 'property-developer', canonical_category = 'property-developer',
  district = 'paphos', luxury = true,
  name_en = 'Leptos Estates', name_el = 'Leptos Estates', name_ro = 'Leptos Estates', name_ar = 'Leptos Estates', name_de = 'Leptos Estates', name_pl = 'Leptos Estates', name_ru = 'Leptos Estates',
  summary_en = 'Leptos Estates is the luxury property developer of the Leptos Group, a Cypriot family company active since 1960. Headquartered in Paphos with offices in Nicosia and Limassol, it builds villas, seafront residences and resorts in Cyprus and Greece.',
  summary_el = 'Η Leptos Estates είναι ο φορέας πολυτελούς ανάπτυξης ακινήτων του Ομίλου Leptos, μιας κυπριακής οικογενειακής εταιρείας με παρουσία από το 1960. Με έδρα την Πάφο και γραφεία σε Λευκωσία και Λεμεσό, κατασκευάζει βίλες, κατοικίες δίπλα στη θάλασσα και resorts σε Κύπρο και Ελλάδα.',
  summary_ro = 'Leptos Estates este dezvoltatorul imobiliar de lux al Grupului Leptos, o companie de familie cipriotă activă din 1960. Cu sediul la Paphos și birouri la Nicosia și Limassol, construiește vile, reședințe pe malul mării și resorturi în Cipru și Grecia.',
  summary_ar = 'ليبتوس إستيتس هي ذراع التطوير العقاري الفاخر في مجموعة ليبتوس، وهي شركة عائلية قبرصية تعمل منذ عام 1960. مقرها الرئيسي في بافوس ولها مكاتب في نيقوسيا وليماسول، وتبني فللاً ومساكن على البحر ومنتجعات في قبرص واليونان.',
  summary_de = 'Leptos Estates ist der Luxus-Projektentwickler der Leptos Group, eines zypriotischen Familienunternehmens, das seit 1960 besteht. Mit Hauptsitz in Paphos und Büros in Nikosia und Limassol baut es Villen, Residenzen am Meer und Resorts auf Zypern und in Griechenland.',
  summary_pl = 'Leptos Estates to deweloper luksusowych nieruchomości z Grupy Leptos, cypryjskiej firmy rodzinnej działającej od 1960 roku. Z siedzibą w Pafos i biurami w Nikozji i Limassol buduje wille, rezydencje nad morzem i kompleksy wypoczynkowe na Cyprze i w Grecji.',
  summary_ru = 'Leptos Estates является девелопером элитной недвижимости группы Leptos, кипрской семейной компании, работающей с 1960 года. Головной офис находится в Пафосе, офисы есть в Никосии и Лимасоле; компания строит виллы, резиденции у моря и курортные комплексы на Кипре и в Греции.',
  address = 'The Leptos House, 111 Apostolou Pavlou Avenue, 8046 Paphos', lat = 34.757208, lng = 32.412227, coords_precision = 'geocoded',
  phone = '+357 26 880 100', email = 'contactus@leptosestates.com', url = 'https://www.leptosestates.com/',
  image = '/partners/leptos/cover.jpg', image_credit = 'Leptos Estates',
  socials = '{"facebook":"https://www.facebook.com/leptosestates","instagram":"https://www.instagram.com/leptos_estates/","linkedin":"https://www.linkedin.com/company/leptos-estates"}'::jsonb,
  tags = array['leptos', 'leptos estates', 'leptos group', 'leptos developers', 'luxury developer', 'property developer', 'real estate', 'villas', 'apartments', 'paphos', 'nicosia', 'limassol', 'cyprus', 'greece']::text[],
  source_url = 'https://www.leptosestates.com/', fetched_at = now(), updated_at = now()
 where slug = 'leptos-estates';

