update public.directory_listings set summary_en = 'Private medical, diagnostic and surgical hospital in Paphos, open 24/7, CHKS-accredited. A member of the group since 2007.', summary_el = 'Ιδιωτικό ιατρικό, διαγνωστικό και χειρουργικό νοσοκομείο στην Πάφο, με λειτουργία όλο το 24ωρο και διαπίστευση CHKS. Μέλος του ομίλου από το 2007.', summary_ro = 'Spital privat de medicină, diagnostic și chirurgie la Paphos, deschis non-stop, acreditat CHKS. Membru al grupului din 2007.', summary_ar = 'مستشفى خاص للطب والتشخيص والجراحة في بافوس، يعمل على مدار الساعة ومعتمد من CHKS. عضو في المجموعة منذ عام 2007.', summary_de = 'Privates Krankenhaus für Medizin, Diagnostik und Chirurgie in Paphos, rund um die Uhr geöffnet, CHKS-akkreditiert. Seit 2007 Mitglied der Gruppe.', summary_pl = 'Prywatny szpital w Pafos: leczenie, diagnostyka i chirurgia, czynny całą dobę, akredytacja CHKS. W grupie od 2007 roku.', summary_ru = 'Частная больница в Пафосе: терапия, диагностика и хирургия, круглосуточно, аккредитация CHKS. В группе с 2007 года.', updated_at = now() where slug = 'iasis-private-hospital-4757';
update public.directory_listings set summary_en = 'Self-catering studios and apartments close to Paphos harbour, next to St. Paul’s Pillar and the Paphos Mosaics.', summary_el = 'Στούντιο και διαμερίσματα αυτοεξυπηρέτησης κοντά στο λιμάνι της Πάφου, δίπλα στον Κίονα του Αποστόλου Παύλου και τα Ψηφιδωτά της Πάφου.', summary_ro = 'Studiouri și apartamente cu autoservire lângă portul Paphos, vecine cu Stâlpul Sf. Pavel și Mozaicurile din Paphos.', summary_ar = 'استوديوهات وشقق خدمة ذاتية قرب ميناء بافوس، بجوار عمود القديس بولس وفسيفساء بافوس.', summary_de = 'Studios und Apartments zur Selbstversorgung nahe dem Hafen von Paphos, neben der Paulussäule und den Mosaiken von Paphos.', summary_pl = 'Studia i apartamenty z aneksem blisko portu w Pafos, obok Kolumny św. Pawła i mozaik Pafos.', summary_ru = 'Студии и апартаменты с кухней рядом с портом Пафоса, возле Столпа апостола Павла и пафосских мозаик.', updated_at = now() where slug = 'basilica-4oa6krw';
