update public.directory_listings set summary_en = 'Adults-only boutique hotel on the cliff above Coral Bay: 100 rooms and suites, all with sea views, and the Anagenisis Spa.', summary_el = 'Boutique ξενοδοχείο μόνο για ενήλικες στον βράχο πάνω από το Κόραλ Μπέι: 100 δωμάτια και σουίτες, όλα με θέα στη θάλασσα, και το Anagenisis Spa.', summary_ro = 'Hotel boutique doar pentru adulți, pe stânca de deasupra golfului Coral Bay: 100 de camere și suite, toate cu vedere la mare, și Anagenisis Spa.', summary_ar = 'فندق بوتيك للبالغين فقط على الجرف المطل على كورال باي: 100 غرفة وجناح بإطلالة بحرية، ومنتجع Anagenisis الصحي.', summary_de = 'Boutique-Hotel nur für Erwachsene auf den Klippen über Coral Bay: 100 Zimmer und Suiten, alle mit Meerblick, und das Anagenisis Spa.', summary_pl = 'Butikowy hotel tylko dla dorosłych na klifie nad Coral Bay: 100 pokoi i apartamentów, wszystkie z widokiem na morze, oraz Anagenisis Spa.', summary_ru = 'Бутик-отель только для взрослых на скале над Корал-Бей: 100 номеров и сьютов, все с видом на море, и спа Anagenisis.', updated_at = now() where slug = 'thalassa-3l4tp3';
