    ('paphos-gardens-fvm4nm', 34.753236, 32.424643),
    ('neapolis-university-pafos-paphos', 34.749421, 32.426605),
    ('iasis-private-hospital-4757', 34.762628, 32.438487)
  ) v(slug, lat, lng)
 where l.slug = v.slug and (l.lat is null or l.lng is null);

