-- 7) Herkunft der Koordinaten notieren, falls die Spalte existiert (Migration vom 14.10.)
do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'directory_listings' and column_name = 'coords_source') then
    execute $q$ update public.directory_listings set coords_source = 'osm'
      where slug in ('leptos-estates', 'armonia-estates-ltd-12525', 'leptos-estates-limassol', 'leptos-vesta-holidays', 'leptos-chestertons-cyprus', 'leptos-resitour-holiday-residences', 'leptos-arena-sports') $q$;
  end if;
end $$;

-- Kontrolle
select slug, type, status, name_en, district, lat, lng, coords_precision, luxury
  from public.directory_listings
 where slug in ('leptos-estates', 'armonia-estates-ltd-12525', 'leptos-estates-limassol', 'leptos-vesta-holidays', 'leptos-chestertons-cyprus', 'leptos-resitour-holiday-residences', 'leptos-arena-sports', 'basilica-4oa6krw')
 order by slug;
